-- supabase/seed.sql (GERADO — não editar à mão, rode scripts/generate-seed-sql.mjs)
-- Fonte: src/server/seed-data.ts (422 SKUs) e src/server/aliases-seed.ts
-- (86 aliases de modelo, 38 aliases de cor).
--
-- Nota sobre cor: COLOR_ALIASES mapeia "preta" -> "Preto" (nome canônico de exibição).
-- Aqui migramos o alias em si (para o motor de matching reconhecer variações de
-- digitação); o nome canônico de cada variante já vem pronto em product_variants.color
-- a partir do catálogo original (seed-data.ts), então nenhuma informação é perdida.
--
-- Idempotente: pode ser rodado mais de uma vez (ON CONFLICT).
begin;

-- products (180)
on conflict (id) do update set name = excluded.name, normalized_name = excluded.normalized_name, active = true;

-- product_variants (421)
on conflict (id) do update set gtin = excluded.gtin, color = excluded.color, normalized_color = excluded.normalized_color, active = true;

-- product_aliases: modelo (86)
on conflict (product_id, normalized_alias, alias_type) where product_id is not null do nothing;

-- product_aliases: cor (38)
on conflict (normalized_alias, alias_type) where product_id is null do nothing;

commit;

-- AVISOS DA GERAÇÃO (1) — nada foi apagado, só não migrado automaticamente:
--   sku_code duplicado no seed, mantida a primeira ocorrência: OUT-GFGCM13-3
